    if isinstance(res,list): res=res[0]
    if res.get('type','').endswith('error'): return None, res.get('error_code')
    c=res.get('content')
    if isinstance(c,dict):
        s=c.get('source',{}); 
        if s.get('type')=='text': return s.get('data'),None
        if s.get('type')=='base64':
            return "\n".join(p.extract_text() for p in PdfReader(io.BytesIO(base64.b64decode(s['data']))).pages),None
